141	function isRecord(value: unknown): value is Record<string, unknown> {
142	  return typeof value === "object" && value !== null && !Array.isArray(value);
143	}
144	
145	/**
146	 * A hooks block with its script paths resolved against `base`.
147	 *
148	 * Only `before_tool` and `after_tool` are touched: `tool_allowlist` and
149	 * `tool_denylist` hold tool-name globs, and rewriting those as paths would turn a
150	 * pattern into a filename the core then refuses to find.
151	 *
152	 * Either spelling, because the file-wide block is a list (the machinery's hooks plus
153	 * whatever the project appended) while a server's own is usually one script. Both
154	 * reach the core, which has accepted both since v0.1.33.
155	 */
156	function absoluteHooks(hooks: Record<string, unknown>, base: string): Record<string, unknown> {
157	  const out: Record<string, unknown> = { ...hooks };
158	  for (const key of HOOK_SCRIPT_KEYS) {
159	    const declared = out[key];
160	    if (Array.isArray(declared)) {
161	      out[key] = declared.map((script) => absolutePath(script, base));
162	    } else if (typeof declared === "string") {
163	      out[key] = absolutePath(declared, base);
164	    }
165	  }
166	  return out;
167	}
168	
169	/**
170	 * One hook path, against `base`.
171	 *
172	 * An already-absolute path is left alone, so an adopter who names one gets what they
173	 * asked for rather than a path joined onto a path. Anything that is not a string is
174	 * returned untouched: this resolves paths, and reporting that one is the wrong type
175	 * belongs to the core, which says so with the file in front of it.
176	 */
177	function absolutePath(script: unknown, base: string): unknown {
178	  if (typeof script !== "string" || script.length === 0) return script;
179	  if (isAbsolute(script)) return script;
180	  // Posix separators: this is written for a Linux runner, and a Windows-style
181	  // separator would reach the core as part of the filename.
182	  // The base is made absolute first, rather than resolving base and script
183	  // together: resolving both rewrites an already-absolute POSIX base onto the
184	  // current drive on Windows, where the tests for this also run.
185	  const from = isAbsolute(base) ? base : resolve(base);
186	  return join(from, script).split("\\").join("/");
187	}
188	
189	/**
190	 * Names in `tools.servers` that would collide with the core's reserved key.
191	 *
192	 * `hooks` at the top level of a tools file is the file-wide hook declaration, not
193	 * a server. A server called `hooks` would be written into that slot and silently
194	 * become one -- the config would say a server exists, the core would read a hook
195	 * configuration, and nothing would report either.
196	 */
197	export function reservedServerNames(tools: ToolsSection | undefined): string[] {
198	  return Object.keys(tools?.servers ?? {}).filter((name) => name === "hooks");
199	}

