83	export function hardenCredentialHolder(log: (message: string) => void): void {
84	  // The three failures below are reported rather than logged, and they are the
85	  // clearest case of what `lib/mcp-report.ts` is for: each one means the
86	  // environment did not give this process a property it was supposed to have, and
87	  // nothing else will ever say so. They also all happen before the server has
88	  // connected, which is why reports are held until it has.
89	  try {
90	    // Imported here rather than at the top: `bun:ffi` is a Bun builtin, and a
91	    // server bundled for another runtime should fail on this line with a message
92	    // about FFI rather than on its first import.
93	    const { dlopen, FFIType } = require("bun:ffi") as typeof import("bun:ffi");
94	    const { symbols } = dlopen("libc.so.6", {
95	      prctl: {
96	        args: [FFIType.i32, FFIType.u64, FFIType.u64, FFIType.u64, FFIType.u64],
97	        returns: FFIType.i32,
98	      },
99	    });
100	    symbols.prctl(PR_SET_DUMPABLE, 0n, 0n, 0n, 0n);
101	    const dumpable = symbols.prctl(PR_GET_DUMPABLE, 0n, 0n, 0n, 0n);
102	    if (dumpable === 0) log("this process is now unreadable to its peers");
103	    else report("warning", `this process could not become unreadable: PR_GET_DUMPABLE reports ${dumpable}`);
104	  } catch (error) {
105	    report("warning", `this process could not become unreadable: ${(error as Error).message}`);
106	  }
107	
108	  const before = process.env.PATH ?? "";
109	  const { writable, unreadable } = classifyPathEntries(before, inspect);
110	  if (writable.length === 0 && unreadable.length === 0) return;
111	
112	  const after = pathWithoutWorldWritable(before, (entry) => inspect(entry) !== "safe");
113	  // Never leave this server without a PATH. `isWorldWritable` answers "yes" for a
114	  // directory it cannot stat, which is right for one entry and catastrophic for
115	  // every entry: an empty PATH makes every `gh` and `git` call in this process
116	  // fail with ENOENT, and the only sign would be one line in a log. Dropping
117	  // everything is not a narrowing, it is a broken stat.
118	  if (after === "") {
119	    report("warning", "every PATH entry looked writable, which cannot be right; PATH was left alone");
120	    return;
121	  }
122	
123	  process.env.PATH = after;
124	  // Reported separately. The first list is the one that matters -- a peer could
125	  // have put a binary there and this process would have run it. The second is
126	  // housekeeping, and saying so keeps the first line meaningful.
127	  if (writable.length > 0) log(`removed WRITABLE directories from PATH: ${writable.join(", ")}`);
128	  if (unreadable.length > 0) log(`also removed ${unreadable.length} PATH entries this process cannot inspect`);
129	}

